CREATE TABLE `transform_job_run` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `job_id` bigint(20) NOT NULL COMMENT 'Identifier for the transform job',
  `run_method` varchar(255) NOT NULL COMMENT 'Method used to execute the transform job',
  `status` varchar(50) NOT NULL COMMENT 'Current status of the transform job (running, completed, failed, etc.)',
  `is_active` bit(1) DEFAULT NULL COMMENT 'True only for currently running jobs, null for the others',
  `start_time` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When the transform job started',
  `end_time` timestamp(6) NULL DEFAULT NULL COMMENT 'When the tranform job completed (null if still running)',
  `message` longtext DEFAULT NULL COMMENT 'Human-readable message about the run; may contain error message in case status is error',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp this transform job run was created.',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp this transform job run was last updated.',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to track transform job executions and their status in the app database';
--;;
CREATE TABLE `transform_job_transform_tag` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `job_id` int(11) NOT NULL COMMENT 'The id of the transform job.',
  `tag_id` int(11) NOT NULL COMMENT 'The id of the transform tag.',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity.',
  `position` int(11) NOT NULL COMMENT 'The ordering position of this tag for the job.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_job_tag` (`job_id`,`tag_id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_transform_job_transform_tag_tag_id` (`tag_id`),
  CONSTRAINT `fk_transform_job_transform_tag_job_id` FOREIGN KEY (`job_id`) REFERENCES `transform_job` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_transform_job_transform_tag_tag_id` FOREIGN KEY (`tag_id`) REFERENCES `transform_tag` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Join table for jobs and tags';
--;;
