CREATE TABLE `transform_run` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `transform_id` int(11) NOT NULL COMMENT 'Identifier for the transform',
  `run_method` varchar(255) NOT NULL COMMENT 'Method used to execute the transform job',
  `status` varchar(50) NOT NULL COMMENT 'Current status of the transform job (running, completed, failed, etc.)',
  `is_active` bit(1) DEFAULT NULL COMMENT 'True only for currently running jobs, null for the others',
  `start_time` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When the transform job started',
  `end_time` timestamp(6) NULL DEFAULT NULL COMMENT 'When the transform job completed (null if still running)',
  `message` longtext DEFAULT NULL COMMENT 'Human-readable message about the run; may contain error message in case status is error',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_active_transform_run` (`transform_id`,`is_active`),
  KEY `idx_transform_run_last_run_idx` (`transform_id`,`start_time`),
  KEY `idx_transform_run_active_runs` (`is_active`,`transform_id`),
  CONSTRAINT `fk_transform_run_transform_id` FOREIGN KEY (`transform_id`) REFERENCES `transform` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to track transform executions and their status in the app database';
--;;
CREATE TABLE `transform_run_cancelation` (
  `run_id` int(11) NOT NULL COMMENT 'The transform_run ID',
  `time` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The time of the request',
  PRIMARY KEY (`run_id`),
  CONSTRAINT `fk_transform_run_cancelation_transform_run_run_id` FOREIGN KEY (`run_id`) REFERENCES `transform_run` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to track the cancelation of transform job executions';
--;;
CREATE TABLE `transform_tag` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` varchar(254) NOT NULL COMMENT 'The name of the transform tag.',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity.',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The time the transform tag was created.',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The time the transform tag was last updated.',
  `built_in_type` varchar(255) DEFAULT NULL COMMENT 'Type of the built-in transform tag: hourly, daily, weekly, monthly.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tags for grouping transforms';
--;;
