CREATE OR REPLACE VIEW `v_alerts` AS with parsed_cron as (select `n`.`id` AS `id`,`ns`.`cron_schedule` AS `cron_schedule`,`ns`.`ui_display_type` AS `ui_display_type`,substring_index(substring_index(`ns`.`cron_schedule`,' ',2),' ',-1) AS `minutes`,substring_index(substring_index(`ns`.`cron_schedule`,' ',3),' ',-1) AS `hours`,substring_index(substring_index(`ns`.`cron_schedule`,' ',4),' ',-1) AS `day_of_month`,substring_index(substring_index(`ns`.`cron_schedule`,' ',6),' ',-1) AS `day_of_week` from (`notification` `n` join `notification_subscription` `ns` on(`n`.`id` = `ns`.`notification_id`)) where `n`.`payload_type` = 'notification/card' and `ns`.`type` = 'notification-subscription/cron'), schedule_info as (select `parsed_cron`.`id` AS `id`,case when `parsed_cron`.`ui_display_type` = 'cron/raw' then 'custom' when `parsed_cron`.`minutes` regexp '^\\*$' or `parsed_cron`.`minutes` regexp '^[0-9]+/[0-9]+$' then 'by the minute' when `parsed_cron`.`day_of_month` <> '*' and (`parsed_cron`.`day_of_week` = '?' or `parsed_cron`.`day_of_week` regexp '^[0-9]#1$' or `parsed_cron`.`day_of_week` regexp '^[0-9]L$') then 'monthly' when `parsed_cron`.`day_of_week` <> '?' and `parsed_cron`.`day_of_week` <> '*' then 'weekly' when `parsed_cron`.`hours` <> '*' then 'daily' else 'hourly' end AS `schedule_type`,case when `parsed_cron`.`day_of_week` regexp '^1' then 'sun' when `parsed_cron`.`day_of_week` regexp '^2' then 'mon' when `parsed_cron`.`day_of_week` regexp '^3' then 'tue' when `parsed_cron`.`day_of_week` regexp '^4' then 'wed' when `parsed_cron`.`day_of_week` regexp '^5' then 'thu' when `parsed_cron`.`day_of_week` regexp '^6' then 'fri' when `parsed_cron`.`day_of_week` regexp '^7' then 'sat' else NULL end AS `schedule_day`,case when `parsed_cron`.`hours` = '*' then NULL when `parsed_cron`.`hours` regexp '^[0-9]+$' then cast(`parsed_cron`.`hours` as signed) when `parsed_cron`.`hours` regexp '^([0-9]+)/[0-9]+$' then cast(substring_index(`parsed_cron`.`hours`,'/',1) as signed) else NULL end AS `schedule_hour` from `parsed_cron`), agg_recipients as (select `nr`.`notification_handler_id` AS `notification_handler_id`,group_concat(`cu`.`email` separator ',') AS `recipients`,group_concat(case when `nr`.`type` = 'notification-recipient/raw-value' then `nr`.`details` else NULL end separator ',') AS `recipient_external` from (`notification_recipient` `nr` left join `core_user` `cu` on(`nr`.`user_id` = `cu`.`id` and `nr`.`type` = 'notification-recipient/user')) group by `nr`.`notification_handler_id`)select `n`.`id` AS `entity_id`,concat('notification_',`n`.`id`) AS `entity_qualified_id`,`n`.`created_at` AS `created_at`,`n`.`updated_at` AS `updated_at`,`n`.`creator_id` AS `creator_id`,`nc`.`card_id` AS `card_id`,concat('card_',`nc`.`card_id`) AS `card_qualified_id`,case when `nc`.`send_condition` = 'has_result' then 'rows' when `nc`.`send_condition` in ('goal_above','goal_below') then 'goal' end AS `alert_condition`,`si`.`schedule_type` AS `schedule_type`,`si`.`schedule_day` AS `schedule_day`,`si`.`schedule_hour` AS `schedule_hour`,`n`.`active` = 0 AS `archived`,`nh`.`channel_type` AS `recipient_type`,`ar`.`recipients` AS `recipients`,`ar`.`recipient_external` AS `recipient_external` from ((((`notification` `n` join `notification_card` `nc` on(`n`.`payload_id` = `nc`.`id`)) join `schedule_info` `si` on(`n`.`id` = `si`.`id`)) left join `notification_handler` `nh` on(`n`.`id` = `nh`.`notification_id`)) left join `agg_recipients` `ar` on(`nh`.`id` = `ar`.`notification_handler_id`)) where `n`.`payload_type` = 'notification/card';
--;;
CREATE OR REPLACE VIEW `v_audit_log` AS (select `audit_log`.`id` AS `id`,case when `audit_log`.`topic` = 'card-create' then 'card-create' when `audit_log`.`topic` = 'card-delete' then 'card-delete' when `audit_log`.`topic` = 'card-update' then 'card-update' when `audit_log`.`topic` = 'pulse-create' then 'subscription-create' when `audit_log`.`topic` = 'pulse-delete' then 'subscription-delete' else `audit_log`.`topic` end AS `topic`,`audit_log`.`timestamp` AS `timestamp`,NULL AS `end_timestamp`,coalesce(`audit_log`.`user_id`,0) AS `user_id`,lcase(`audit_log`.`model`) AS `entity_type`,`audit_log`.`model_id` AS `entity_id`,case when `audit_log`.`model` = 'Dataset' then concat('card_',`audit_log`.`model_id`) when `audit_log`.`model_id` is null then NULL else concat(lcase(`audit_log`.`model`),'_',`audit_log`.`model_id`) end AS `entity_qualified_id`,`audit_log`.`details` AS `details` from `audit_log` where `audit_log`.`topic` not in ('card-read','card-query','dashboard-read','dashboard-query'));
--;;
